const raw = $json.text || '';
const get = (k) => { const m = raw.match(new RegExp('^\\s*' + k + '\\s*:\\s*(.*)$', 'mi')); return m ? m[1].trim() : ''; };
const none = (v) => !v || /^(none|null|n\/a|-)$/i.test(v);
let type = get('PROJECT_TYPE').toUpperCase();
if (!['IT', 'EVENT', 'CREATIVE'].includes(type)) type = 'IT';
const budgetRaw = get('BUDGET_THB').replace(/[, ]/g, '');
const budget = none(budgetRaw) ? null : Number(budgetRaw.replace(/[^0-9.]/g, ''));
const hasBudget = budget !== null && !isNaN(budget) && budget > 0;
const deadline = none(get('DEADLINE')) ? null : get('DEADLINE');
const missing = none(get('MISSING')) ? [] : get('MISSING').split(';').map(s => s.trim()).filter(Boolean);
const questions = none(get('QUESTIONS')) ? [] : get('QUESTIONS').split('|').map(s => s.trim()).filter(Boolean);
const PENDING = '[รอระบุ / Pending Confirmation]';
return { json: {
  brief: $('Chat Trigger').first().json.chatInput,
  project_name: get('PROJECT_NAME') || 'โครงการไม่ระบุชื่อ',
  goal: get('GOAL') || PENDING,
  project_type: type,
  has_budget: hasBudget,
  budget_thb: hasBudget ? budget : PENDING,
  deadline: deadline || PENDING,
  missing,
  questions
} };

