const ctx = $('Project Context').first().json;

const getText = (nodeName) => {
  try {
    const value = $(nodeName).first().json;
    return value.output ?? value.text ?? value.report ?? '(ไม่มีข้อมูลจากโหนดนี้)';
  } catch (error) {
    return '(ไม่พบข้อมูลจากโหนด ' + nodeName + ')';
  }
};

const sections = [];
sections.push('# ' + (ctx.project_name || 'รายงานวิเคราะห์โครงการ'));
sections.push('> Framework: ' + (ctx.framework_mode || '[รอระบุ]'));

if ((ctx.questions && ctx.questions.length) || (ctx.missing && ctx.missing.length)) {
  let pending = '## ⚠️ ข้อมูลที่ต้องยืนยัน (Pending Confirmation)';
  (ctx.missing || []).forEach((item) => {
    pending += '\n- ขาด: ' + item;
  });
  (ctx.questions || []).forEach((question, index) => {
    pending += '\n' + (index + 1) + '. ' + question;
  });
  sections.push(pending);
}

sections.push(
  '## Stage 2: Charter, WBS และ Test Plan\n\n' +
  getText('Stage 2 - WBS & Test Plan')
);
sections.push(
  '## Stage 3: งบประมาณ (' + (ctx.has_budget ? 'Top-Down' : 'Bottom-Up') + ')\n\n' +
  getText('Stage 3 - Smart Budget')
);
sections.push(
  '## Stage 4: ความเสี่ยงและ Change Control\n\n' +
  getText('Stage 4 - Risk & Change Control')
);
sections.push(
  '## รายงานสรุปสำหรับผู้บริหาร\n\n' +
  getText('Stage 5 - Complete Reports')
);

const finalReport = sections.join('\n\n---\n\n').trim();

if (!finalReport) {
  throw new Error('ไม่สามารถสร้างรายงานตอบกลับได้: finalReport ว่าง');
}

// n8n Chat Trigger can return the final text from the output field.
return [{ json: { output: finalReport, text: finalReport } }];
